-- VELLURE · peças reais (fotos das modelos do site antigo)
-- Rode DEPOIS do schema.sql, no SQL Editor do Supabase. Pode rodar de novo sem duplicar.

on conflict (slug) do update set name = excluded.name, description = excluded.description, sort = excluded.sort;

-- esconde as peças fictícias de demonstração
update public.products set is_active = false where images = '{}' or images is null;

on conflict (slug) do update set name = excluded.name, subtitle = excluded.subtitle, category = excluded.category, price = excluded.price, sizes = excluded.sizes, images = excluded.images, is_active = true;
